-- One login = one company. Company code, per-company mobile/e-mail, one active membership per user.
-- Generated by drizzle-kit, then reordered by hand so existing data is converted before the
-- constraints are added.

DROP INDEX "users_mobile_key";--> statement-breakpoint
ALTER TABLE "companies" ADD COLUMN "code" text;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "company_id" uuid;--> statement-breakpoint
ALTER TABLE "users" ADD CONSTRAINT "users_company_id_companies_id_fk" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint

-- 1. Company codes for existing companies: upper-case letters / digits of the short name,
--    3-10 characters, a number added when two would clash.
do $$
declare
  c record;
  base text;
  candidate text;
  i int;
begin
  for c in select id, label from public.companies order by created_at, id loop
    base := left(upper(regexp_replace(c.label, '[^A-Za-z0-9]', '', 'g')), 8);
    if length(base) < 3 then base := rpad(base, 3, 'X'); end if;
    candidate := base;
    i := 1;
    while exists (select 1 from public.companies where code = candidate) loop
      i := i + 1;
      candidate := left(base, 10 - length(i::text)) || i::text;
    end loop;
    update public.companies set code = candidate where id = c.id;
    raise notice 'company % (%) -> code %', c.label, c.id, candidate;
  end loop;
end $$;--> statement-breakpoint
ALTER TABLE "companies" ALTER COLUMN "code" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_code_check" CHECK (code ~ '^[A-Z0-9]{3,10}$');--> statement-breakpoint
CREATE UNIQUE INDEX "companies_code_key" ON "companies" USING btree ("code") WHERE cancelled_at is null;--> statement-breakpoint

-- 2. People in several companies keep their first company; every other company gets its own
--    account (same name / mobile / e-mail, new random password, Owner resets it from Users & roles).
do $$
declare
  m record;
  new_id uuid;
  u record;
begin
  for m in
    select * from (
      select mm.id, mm.user_id, mm.company_id,
             row_number() over (partition by mm.user_id order by mm.created_at, mm.id) as rn
        from public.memberships mm
       where mm.cancelled_at is null) x
     where x.rn > 1
  loop
    select * into u from public.users where id = m.user_id;
    new_id := gen_random_uuid();
    insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
                            raw_user_meta_data, created_at, updated_at)
    values (new_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
            'u-' || new_id || '@lrm.invalid',
            extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')), now(),
            jsonb_build_object('name', u.name, 'mobile', null, 'email_placeholder', true), now(), now());
    update public.users
       set mobile = u.mobile, email = u.email, name = u.name
     where id = new_id;
    update public.memberships set user_id = new_id where id = m.id;
    update public.drivers set user_id = new_id where user_id = m.user_id and company_id = m.company_id;
    raise notice 'split user % (%): company % now has account % (% / %)',
      u.name, m.user_id, m.company_id, new_id, u.mobile, u.email;
  end loop;
end $$;--> statement-breakpoint

-- 3. Every user points at the company of their active membership.
update public.users u set company_id = m.company_id
  from public.memberships m
 where m.user_id = u.id and m.cancelled_at is null;--> statement-breakpoint
CREATE UNIQUE INDEX "memberships_one_company_per_user" ON "memberships" USING btree ("user_id") WHERE cancelled_at is null;--> statement-breakpoint
CREATE UNIQUE INDEX "users_company_mobile_key" ON "users" USING btree ("company_id","mobile") WHERE mobile is not null;--> statement-breakpoint
CREATE UNIQUE INDEX "users_company_email_key" ON "users" USING btree ("company_id",lower("email")) WHERE email is not null;--> statement-breakpoint

-- A new membership puts the user in that company.
create or replace function app.tg_membership_user_company() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.cancelled_at is null then
    update public.users set company_id = new.company_id, updated_at = now()
     where id = new.user_id and company_id is distinct from new.company_id;
  end if;
  return new;
end $$;--> statement-breakpoint
create trigger e_membership_user_company after insert on public.memberships
  for each row execute function app.tg_membership_user_company();--> statement-breakpoint

-- 4. Login: company code + mobile / e-mail. Same answer whether the code or the person is wrong.
drop function app.login_lookup(text);--> statement-breakpoint
create function app.login_lookup(p_code text, p_identifier text)
returns table (user_id uuid, auth_email text)
language sql stable security definer set search_path = '' as $$
  select u.id, a.email::text
    from public.companies c
    join public.memberships m on m.company_id = c.id and m.cancelled_at is null
    join public.users u on u.id = m.user_id and u.cancelled_at is null
    join auth.users a on a.id = u.id
   where c.cancelled_at is null
     and c.code = upper(btrim(p_code))
     and ((p_identifier ~ '^[0-9]{10}$' and u.mobile = p_identifier)
          or (u.email is not null and lower(u.email) = lower(btrim(p_identifier))))
   limit 1;
$$;--> statement-breakpoint

-- 5. Invites never attach an existing login to another company any more.
drop function app.find_user(text, text);--> statement-breakpoint
-- Password reset: the target belongs to a company the caller owns.
create or replace function app.can_reset_password(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select auth.uid() is not null and exists (
    select 1 from public.memberships m
      join public.memberships o on o.company_id = m.company_id
     where m.user_id = target and m.cancelled_at is null
       and o.user_id = auth.uid() and o.role = 'owner' and o.cancelled_at is null);
$$;--> statement-breakpoint

-- 6. Registering a company (login page): company + owner membership + number series in one
--    transaction. The Auth user is made first by the server (admin API). Not callable by
--    signed-in users, so nobody can add a second company to an account.
drop function app.create_company(text, text, text, text, text);--> statement-breakpoint
create function app.register_company(p_owner uuid, p_code text, p_label text, p_name text,
                                     p_city text, p_gstin text, p_pan text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  company uuid;
  fy text := app.financial_year((now() at time zone 'Asia/Kolkata')::date);
begin
  insert into public.companies (code, label, name, city, gstin, pan, created_by, updated_by, lr_copies)
  values (upper(btrim(p_code)), p_label, p_name, coalesce(p_city, ''), p_gstin, p_pan, p_owner, p_owner,
          array['Consignor', 'Consignee', 'Driver', 'Office'])
  returning id into company;
  insert into public.memberships (company_id, user_id, role, created_by, updated_by)
  values (company, p_owner, 'owner', p_owner, p_owner);
  insert into public.number_series (company_id, series, fy, prefix, next_no)
  values (company, 'lr', fy, '', 1), (company, 'freight_bill', fy, '', 1),
         (company, 'tax_invoice', fy, '', 1);
  return company;
end $$;--> statement-breakpoint
create function app.company_code_taken(p_code text, p_except uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.companies c
                  where c.code = upper(btrim(p_code)) and c.id is distinct from p_except
                    and c.cancelled_at is null);
$$;--> statement-breakpoint

-- Invites: the person with this mobile / e-mail in THIS company (even if removed earlier, so they
-- can be added back). Only for people who manage the company.
create function app.find_company_user(p_company uuid, p_mobile text, p_email text)
returns table (user_id uuid, name text, active boolean)
language sql stable security definer set search_path = '' as $$
  select u.id, u.name,
         exists (select 1 from public.memberships m
                  where m.user_id = u.id and m.company_id = p_company and m.cancelled_at is null)
    from public.users u
   where u.company_id = p_company and u.cancelled_at is null
     and app.can(p_company, 'company.manage')
     and (u.mobile = p_mobile or (p_email is not null and lower(u.email) = lower(p_email)))
   limit 1;
$$;--> statement-breakpoint
-- The real e-mail of someone made with a placeholder Auth e-mail travels in the metadata
-- (Auth e-mails are globally unique; the same person can have an account in each company).
create or replace function app.tg_auth_user_created() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  placeholder boolean := coalesce((new.raw_user_meta_data ->> 'email_placeholder')::boolean, false);
begin
  insert into public.users (id, name, email, mobile)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'name', ''),
    case when placeholder then nullif(new.raw_user_meta_data ->> 'email', '') else new.email end,
    nullif(new.raw_user_meta_data ->> 'mobile', '')
  )
  on conflict (id) do update set email = excluded.email;
  return new;
end $$;--> statement-breakpoint

-- Dev / test cleanup also lets go of the users pointing at the company.
create or replace function app.purge_company(company uuid) returns void
language plpgsql set search_path = '' as $$
begin
  if not app.purging() then
    raise exception 'purge_company needs app.purge = on (dev / tests only)' using errcode = 'insufficient_privilege';
  end if;
  delete from public.audit_log where company_id = company;
  delete from public.payment_allocations where company_id = company;
  delete from public.payments where company_id = company;
  delete from public.freight_bill_lines where company_id = company;
  delete from public.freight_bills where company_id = company;
  delete from public.pods where company_id = company;
  delete from public.lr_invoices where company_id = company;
  delete from public.lr_items where company_id = company;
  delete from public.lrs where company_id = company;
  delete from public.tax_invoice_lines where company_id = company;
  delete from public.tax_invoices where company_id = company;
  delete from public.import_mappings where company_id = company;
  delete from public.import_batches where company_id = company;
  delete from public.trucks where company_id = company;
  delete from public.drivers where company_id = company;
  delete from public.items where company_id = company;
  delete from public.parties where company_id = company;
  delete from public.memberships where company_id = company;
  update public.users set company_id = null where company_id = company;
  delete from public.number_series where company_id = company;
  delete from public.companies where id = company;
end $$;--> statement-breakpoint

revoke execute on function app.login_lookup(text, text), app.register_company(uuid, text, text, text, text, text, text),
  app.company_code_taken(text, uuid), app.find_company_user(uuid, text, text) from public;--> statement-breakpoint
grant execute on function app.login_lookup(text, text), app.company_code_taken(text, uuid)
  to anon, authenticated, service_role;--> statement-breakpoint
grant execute on function app.find_company_user(uuid, text, text) to authenticated, service_role;--> statement-breakpoint
grant execute on function app.register_company(uuid, text, text, text, text, text, text) to service_role;
